// Spike R1, browser half (docs/ographis-port-plan.md): rasters in the egui app over DuckDB-Wasm,
// through the real worker bridge. A GeoTIFF dropped on the page becomes a Reader whose areas
// RasterToPolygonCoercer makes; a COG opened by URL is read by range requests, and
// PointOnRasterValueExtractor samples it. The rasters are generated by a Rust test, not committed.
import { execFileSync } from "node:child_process";
import { mkdtempSync, readFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { test, expect } from "@playwright/test";

const out = mkdtempSync(join(tmpdir(), "gm-browser-rasters-"));
execFileSync(
  "cargo",
  ["test", "--release", "-p", "geomarmot-io", "--test", "raster", "write_browser_rasters", "--", "--ignored"],
  { cwd: new URL("..", import.meta.url).pathname, env: { ...process.env, GM_RASTER_OUT: out }, stdio: "ignore" },
);
const gradient = readFileSync(join(out, "gradient.tif"));
const classes = readFileSync(join(out, "classes.tif"));

// Points in LV95 coordinates (labelled by CoordinateSystemSetter): pixel centres (3, 7) and
// (4095, 4095), and one outside the raster.
const points = JSON.stringify({
  type: "FeatureCollection",
  features: [
    [2600035, 1199925, "a"],
    [2640955, 1159045, "b"],
    [2500000, 1100000, "outside"],
  ].map(([x, y, name]) => ({
    type: "Feature",
    properties: { name },
    geometry: { type: "Point", coordinates: [x, y] },
  })),
});

const waitFor = (page, check, arg, timeout = 60_000) => page.waitForFunction(check, arg, { timeout, polling: 100 });

test("a dropped GeoTIFF becomes areas, also after an engine restart", async ({ page }) => {
  await page.goto("/app.html");
  await waitFor(page, () => window.__app);
  await page.evaluate((bytes) => window.__app.open("classes.tif", new Uint8Array(bytes)), [...classes]);
  await waitFor(page, () => window.__app.state().nodes === 1 && window.__app.state().status === "Ready.");
  await waitFor(page, () => window.__app.state().rows === 1);
  expect(await page.evaluate(() => window.__app.state().columns)).toContain("crs");
  // A restarted DuckDB worker gets the footprint back (addSource replay); the pixels never left.
  await page.evaluate(() => globalThis.gmBridge.restart());
  await page.evaluate(() => {
    window.__app.command({ add: "RasterToPolygonCoercer", params: { band: "1" }, from: [0, 0] });
    window.__app.command({ select: [1, 0] });
  });
  await waitFor(page, () => window.__app.state().rows === 2);
  const cells = await page.evaluate(() =>
    window.__app
      .state()
      .cells.map((r) => r[0])
      .sort(),
  );
  expect(cells).toEqual(["1.0", "2.0"]);
});

test("a COG by URL is sampled by range requests", async ({ page }) => {
  let fetched = 0;
  await page.route("**/data/gradient.tif", async (route) => {
    const range = route.request().headers()["range"];
    const [a, b] = range.replace("bytes=", "").split("-").map(Number);
    const body = gradient.subarray(a, Math.min(b, gradient.length - 1) + 1);
    fetched += body.length;
    await route.fulfill({
      status: 206,
      headers: { "Content-Range": `bytes ${a}-${a + body.length - 1}/${gradient.length}`, "Accept-Ranges": "bytes" },
      body,
    });
  });
  await page.goto("/app.html");
  await waitFor(page, () => window.__app);
  await page.evaluate(() => window.__app.command({ open_url: new URL("data/gradient.tif", document.baseURI).href }));
  await waitFor(page, () => window.__app.state().nodes === 1 && window.__app.state().status === "Ready.");
  await page.evaluate((text) => window.__app.open("points.geojson", new TextEncoder().encode(text)), points);
  await waitFor(page, () => window.__app.state().nodes === 2 && window.__app.state().status === "Ready.");
  await page.evaluate(() => {
    window.__app.command({ add: "CoordinateSystemSetter", params: { crs: "EPSG:2056" }, from: [1, 0] });
    window.__app.command({ add: "PointOnRasterValueExtractor", params: { band: "1" }, from: [2, 0], raster: [0, 0] });
    window.__app.command({ select: [3, 0] });
  });
  await waitFor(page, () => window.__app.state().rows === 3);
  const state = await page.evaluate(() => window.__app.state());
  const value = state.columns.indexOf("raster_value");
  const name = state.columns.indexOf("name");
  const got = Object.fromEntries(state.cells.map((r) => [r[name], r[value]]));
  expect(got).toEqual({ a: "7003.0", b: "4099095.0", outside: "NULL" });
  console.log(`COG over HTTP in the browser: ${gradient.length} bytes, fetched ${fetched}`);
  expect(fetched).toBeLessThan(gradient.length / 4);
});
